INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-015', 'DEC', 'P2', 'OPEN', NULL, NULL, 'IS THE R2 MINING OBLIGATION PER SOURCE OR PER (SOURCE, SLUG)? THE REPOSITORY HOLDS BOTH ANSWERS AND THEY ONLY AGREED WHILE EVERY SOURCE HAD ONE SLUG. citation_mining''s PRIMARY KEY is (slug, local_ref_id) -- per-slug, one mining row per source per topic. evidence_sources.citation_mining_status is a SINGLE FLAG PER SOURCE, and test_db_integrity C08 asserts a per-source biconditional over it (''mined'' iff a non-deferred mining row resolves to it). log_mining''s own docstring says ''Keyed on the global ref_id'', contradicting the PK of the table it writes. Under single-slug filing these were indistinguishable. Cross-slug filing made them diverge and the divergence is now IN THE DATA: derive it rather than quoting -- select ref_id, count(distinct slug) from source_slug_links group by 1 having count(distinct slug)>1, against count(*) from citation_mining per ref_id. GAP-011''s FIX DID NOT DECIDE THIS, deliberately. It made citation_mining_completeness consistently PER-SOURCE, which is what that check''s stated purpose asks (GAP-283/RULE 124: did a session add a Tier 1-2 source without mining it) and what its primary cm join already did; the legacy cm2 fallback was the only half asking per-slug, and it was ANDed into the per-source question, which is the defect. THE SUBSTANTIVE QUESTION IS UNTOUCHED: mining a source reads its reference list, and a reference list does not change per topic -- that argues per-source. But the YIELD is screened for relevance to a slug, and the same reference list screened for a different slug can admit different work -- that argues a per-slug SCREENING obligation distinct from the mining one. If the second is real, a source cross-filed to four slugs owes three further screening passes and nothing currently records or demands them. RESOLUTION PATH: rule on whether mining and screening are one obligation or two. If two, they need two homes -- citation_mining is already keyed for the per-slug half, and the per-source flag on evidence_sources is already keyed for the other; today one fact is written in both places, which is rule 5.', '2026-09-18 05:46', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 05:46', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', NULL, NULL, NULL, NULL, NULL);